sys_variable_value.value:
(function execute(inputs, outputs) {

var convertedValue = inputs.brl_amount * inputs.exchange_rate;
var formattedValue = convertedValue.toFixed(2);

outputs.usd_amount = formattedValue;

})(inputs, outputs);

